catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    // Skip if form is loading or field was cleared
    if (isLoading || newValue === '') {
        return;
    }

    // Clear stale messages
    g_form.clearMessages();

    var start = newValue;

    // --- NEW: reject start dates in the past ---
    // Catalog date/time values arrive as "YYYY-MM-DD HH:mm:ss".
    // JavaScript's Date wants a "T" between date and time.
    var startDate = new Date(start.replace(' ', 'T'));
    var now = new Date();

    if (startDate < now) {
        g_form.clearValue('start_date_time');
        g_form.showFieldMsg('start_date_time',
            'Start date/time cannot be in the past', 'error');
        return;   // stop here — no point checking end date
    }

    // --- existing check: end must not be before start ---
    var end = g_form.getValue('end_date_time');

    if (end && end < start) {
        g_form.clearValue('end_date_time');
        g_form.showFieldMsg('end_date_time',
            'End date/time should not be before the Start date/time', 'error');
    }
}
